{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.grn_issues_joined AS WITH voucher_base AS ( SELECT LOWER( REGEXP_REPLACE( CONCAT( COALESCE(GRN_PREFIX,\'\'), \'-\', COALESCE(TO_VARCHAR(TRUNC(GRN_NUMBER)), \'\') ), \'[^a-z0-9]+\', \'\' ) ) || \'|\' || REGEXP_REPLACE( REGEXP_REPLACE(LOWER(COALESCE(TO_PARTY,\'\')), \'snitch\', \'\'), \'[^a-z0-9]+\', \'\' ) AS RFID_JOIN_KEY, CASE WHEN COALESCE(QUANTITY, 0) = 0 THEN \'GRN Pending\' ELSE \'GRN Done\' END AS GRN_STATUS, CASE WHEN UPPER(TRIM(TO_PARTY)) IN (\'SNITCH - WH - YELHANKA 2\', \'WH - YELHANKA 2\') THEN \'SAPL-WH2\' WHEN UPPER(TRIM(TO_PARTY)) = \'SNITCH - WH - NORTH\' THEN \'SAPL-NORTH-TAURU\' ELSE TRIM(TO_PARTY) END AS WAREHOUSE_NAME, * FROM snitch_db.maplemonk.logic_purchase_voucher ), issue_base AS ( SELECT CREATED_AT_DATE, UPDATED_AT_DATE, EVIDENCE_WITH_HTTPS, ID AS ISSUE_ID, QTY AS ISSUE_QTY, SKU, \"Issue\" as ISSUE, VENDOR AS VENDOR_ISSUE, COMMENTS, EVIDENCE, PO_NUMBER, SUB_ISSUE, CREATED_AT AS ISSUE_CREATED_AT, CREATED_BY, INVOICE_NUMBER, LAST_UPDATED_AT AS ISSUE_LAST_UPDATED_AT, LOWER(REGEXP_REPLACE(COALESCE(SUB_ISSUE,\'\'), \'[^a-z0-9]+\', \'\')) AS SUB_ISSUE_KEY FROM snitch_db.maplemonk.issues_factory_sorted ), subissue_map AS ( SELECT * FROM VALUES (\'Shade variations\', 10, 75), (\'Double barcode\', 9, 66.66666667), (\'Shortage/Excess\', 9, 33.33333333), (\'Size mismatch\', 9, 58.33333333), (\'Costing issues\', 8, 56.25), (\'Wrong barcode\', 7, 107.1428571), (\'Without barcode\', 7, 107.1428571), (\'Packing conditions not as per SOP\', 6, 75), (\'Relevant documents not available (QC docs / CAD file / packing list etc.)\', 5, 60), (\'Costing not matching with invoice\', 5, 90), (\'Qty mismatch (QC report vs invoice qty)\', 5, 60), (\'Invoice issues (size-level missing / PO number missing / SKU missing)\', 4, 131.25), (\'PO issues (expired / not available / entity names mismatch)\', 3, 100) AS subissue_map (SUB_ISSUE_RAW, SEVERITY, RATE) ), subissue_norm AS ( SELECT LOWER(REGEXP_REPLACE(SUB_ISSUE_RAW, \'[^a-z0-9]+\', \'\')) AS SUB_ISSUE_KEY, SEVERITY, RATE FROM subissue_map ), rfid_base AS ( SELECT LOWER(REGEXP_REPLACE(COALESCE(CAST(\"Doc No\" AS VARCHAR), \'\'), \'[^a-z0-9]+\', \'\')) || \'|\' || REGEXP_REPLACE( REGEXP_REPLACE(LOWER(COALESCE(CAST(\"Site Name\" AS VARCHAR),\'\')), \'snitch\', \'\'), \'[^a-z0-9]+\', \'\' ) AS RFID_JOIN_KEY, \"Doc No\" AS DOC_NO, \"Site Name\" AS SITE_NAME, \"Matching Status\" AS MATCHING_STATUS, \"Scanning Status\" AS SCANNING_STATUS FROM snitch_db.maplemonk.s3_rfid_inward WHERE \"Matching Status\" IS NOT NULL ) SELECT v.*, r.MATCHING_STATUS, r.SCANNING_STATUS, r.DOC_NO, r.SITE_NAME, CASE WHEN r.MATCHING_STATUS IS NULL THEN NULL WHEN LOWER(r.MATCHING_STATUS) = \'pending\' THEN \'NON RFID\' ELSE \'RFID\' END AS RFID_STATUS, i.ISSUE_ID, i.CREATED_AT_DATE AS ISSUE_CREATED_AT_DATE, i.UPDATED_AT_DATE AS ISSUE_UPDATED_AT_DATE, i.EVIDENCE_WITH_HTTPS, i.ISSUE_QTY, i.SKU AS ISSUE_SKU, i.ISSUE, i.SUB_ISSUE, i.VENDOR_ISSUE, i.COMMENTS, i.EVIDENCE, i.PO_NUMBER AS PO_NUMBER_ISSUE, i.INVOICE_NUMBER AS ISSUE_INVOICE_NUMBER, i.ISSUE_CREATED_AT, i.CREATED_BY AS ISSUE_CREATED_BY, i.ISSUE_LAST_UPDATED_AT, COALESCE(m.SEVERITY, 0) AS ISSUE_SEVERITY, COALESCE(m.RATE, 0) AS ISSUE_RATE, COALESCE(m.SEVERITY, 0) * COALESCE(m.RATE, 0) AS ISSUE_DEBIT_AMOUNT, CASE WHEN i.ISSUE_ID IS NULL THEN 0 ELSE 1 END AS HAS_DISCREPANCY FROM voucher_base v LEFT JOIN issue_base i ON TRIM(CAST(v.LOT_NUMBER AS VARCHAR)) = TRIM(CAST(i.PO_NUMBER AS VARCHAR)) LEFT JOIN rfid_base r ON v.RFID_JOIN_KEY = r.RFID_JOIN_KEY LEFT JOIN subissue_norm m ON i.SUB_ISSUE_KEY = m.SUB_ISSUE_KEY;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            